+                phase_label_name: '',
+                stale_labels_removed: [],
+                reason: 'No phase label name provided',
+              };
+            }
+          
+            try {
+              await github.rest.issues.addLabels({
+                owner: context.repo.owner,
+                repo: context.repo.repo,
+                issue_number: issueNumber,
+                labels: [label],
+              });
